const accounts = new Map<string, Account>();
accounts.set("acct-marcus", {
  id: "acct-marcus", email: "marcus@example.com", identityVerified: false, mfaEnabled: false,
  usedSteps: [], backups: [], recoveryAttempts: 0, recoveryLocked: 0
